import {freshState,sanitizeState,STORAGE_KEY} from './model.js?v=0.31.0';
export const SAVED_GUIDES_KEY='fieldguide-saved-guides-v1';
export function savedGuides(storage){const raw=storage.getItem(SAVED_GUIDES_KEY);if(!raw)return [];const parsed=JSON.parse(raw);if(parsed.version!==1||!Array.isArray(parsed.guides)||parsed.guides.some(g=>!g||typeof g.id!=='string'||typeof g.savedAt!=='string'||g.data?.version!==1))throw Error('Saved guides could not be read');return parsed.guides;}
function saveBeforeReplacing(current,next,storage,now){const raw=storage.getItem(STORAGE_KEY);if(raw&&JSON.parse(raw)?.version!==1)throw Error('Current draft could not be read');const guides=savedGuides(storage),savedAt=now.toISOString(),id=savedAt+'-'+guides.length;guides.push({id,savedAt,data:structuredClone(current)});storage.setItem(SAVED_GUIDES_KEY,JSON.stringify({version:1,guides}));storage.setItem(STORAGE_KEY,JSON.stringify(next));return next;}
export function restartGuide(current,storage,now=new Date()){const next=freshState();next.profile=structuredClone(current.profile);next.careerLibrary=structuredClone(current.careerLibrary);next.profileJourney.started=true;next.guide.entry='assessment';next.guide.lastRoute='journey/lifestyle';return saveBeforeReplacing(current,next,storage,now);}
export function restoreSavedGuide(current,id,storage,now=new Date()){const found=savedGuides(storage).find(g=>g.id===id);if(!found)throw Error('Saved guide not found');const next=sanitizeState(found.data);return saveBeforeReplacing(current,next,storage,now);}
export function resetAllData(storage){storage.removeItem(STORAGE_KEY);storage.removeItem(SAVED_GUIDES_KEY);return freshState();}
